                { t: "不存在，因为没有任何人见过它。", verdict: "weak", reply: "结论可能对，判据不对：这个理由对「数」「明天」都不成立，而你不会因此说数不存在。用「见过」当判据会让你在抽象对象上全军覆没。把理由换成「我的理论不需要它」，你的回答才站得住。" }
