            { s: "第一节：案例设定与直觉盘点", d: "完整给出设定（手术、两半球、两个成功者、他们都记得你的一生），列出四条可能回答，指出每条的逻辑代价。" },
            { s: "第二节：传递性论证", d: "写出同一性的传递性，用归谬排除「两个都是我」，说明剩下的选择只有「都不是」与「改问法」。" },
            { s: "第三节：价值层面的检验", d: "用责任与关切两个具体场景检验「改问法」的后果，给出你的判断并承认代价。" },
            { s: "结论：你保留了什么、放弃了什么", d: "明确写出你的立场放弃了哪条日常直觉——不写这一句的文章不算完成。" }
