          md: "你手上有一本全国公路图册，你的车此刻停在杭州。你说「我本来可以今晚到南京」——这句话听起来像在谈一个不存在的地方，其实它说的是：在图册上，从杭州出发沿某条路走，存在一条通往南京的路线，而这条路线的距离在你的汽油与时间预算之内。\n\n把「可能」当成图册上另有其地，好处立刻显现：含「本来可以」「必然」「万一」的句子可以像地理陈述一样被检验——找出相关的那些地点（对本书来说：与当前处境在相关方面最接近的那些路线），再看在那里会发生什么。这就是**可能世界（possible worlds）**作为语义工具的核心想法：不必先承认它们真实存在，只要把它们当作「求值用的地点」就能让模态语句有真假可言。\n\n类比也有边界，而边界正是第 3 讲的难题所在：地图册的地点由公路与距离决定，可能世界之间的「接近」由什么决定？如果「我本来可以今晚到南京」为真，是因为存在一个世界我在南京，那么哪个世界算「本来可以」的那个——汽油够但路上爆胎的那个算不算？这需要一条**接近性（closeness）**的判定规则，而规则本身不是图册给的。地图册比喻还漏掉一件更重要的事：地图上的地点都是现实存在的（都在同一本图册里），而可能世界按定义不是现实的——这个差别正是模态实在论争论的起火点。"
