      flashcards: [
        { id: "philo-metaphysics-3-f1", kind: "term", front: "可能世界（possible world）", back: "可能性语义里的求值装置：一个世界是一个完整的赋值方案。□P（必然 P）在所有可及世界为真；◇P（可能 P）在至少一个可及世界为真。注意它不是「将来的状态」也不是「远方的星球」。", hint: "先问「从哪个世界看、能看多远」。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f2", kind: "term", front: "de dicto 与 de re", back: "de dicto 指模态词管整个命题（□∃x Fx：存在 F 这件事是必然的）；de re 指模态属性归给特定对象（∃x □Fx：有一个对象必然地是 F）。区别的后果：承诺不同、逻辑规律不同。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f3", kind: "figure", front: "克里普克（Saul A. Kripke, 1940–2022）", back: "美国逻辑学家与哲学家。1959、1963 年两篇论文给出模态逻辑的关系语义（可能世界语义）；1970 年普林斯顿三次讲演整理为《命名与必然性》(1980)，提出严格指示词、必然后验与起源本质论。他对把可能世界当作真实对象持保留态度。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f4", kind: "term", front: "严格指示词（rigid designator）", back: "在每一个可能世界都指称同一个对象的词项。专名（如「晨星」）与自然种类词（如「水」）都被 Kripke 视为严格指示词；而「清晨可见的那颗星」这类摹状词不是——它在别的世界可能指别的东西。严格性是把经验同一性升级为必然性的关键。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f5", kind: "term", front: "本质属性（essential property）", back: "对象 x 在一切 x 存在的可能世界都具有、且失去它就不再是 x 的属性。相对的是偶然属性（accidental property）。例：Kripke 主张个体的起源是本质的——你不可能出生于另一对父母。难点：判断本质需要跨世界识别同一个体。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f6", kind: "argument", front: "「水是 H₂O」必然性的论证（Kripke 路线）", back: "P1：「水」是严格指示词，在一切世界指同一种物质。P2：经验发现现实中的水是 H₂O。P3：若某物质在现实世界与水同一，则由 P1，它在一切世界都与水同一。C：水必然是 H₂O（必然后验）。最弱前提是 P1：严格性依赖因果历史式的指称理论，这一步是争论焦点。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f7", kind: "position", front: "模态实在论（modal realism, David Lewis）", back: "主张可能世界与我们的世界是同类的具体对象，真实存在，只是彼此没有因果与时空联系。「必然」被分析为「在所有世界为真」。它换来的收益：省掉模态算子、倾向性、命题等实体，把模态问题变成对世界的量化问题——这是一笔「多订实体、少订概念」的交易。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f8", kind: "argument", front: "巴坎公式（Barcan Formula）与其失效", back: "∀x □Fx → □∀x Fx。在可变论域（不同世界对象不同）下失效。反例：w1 论域只有 {a} 且 Fa 真，w1 可及 w2，w2 论域 {a,b} 且 Fb 假；则 ∀x □Fx 在 w1 真而 □∀x Fx 在 w1 假。它区分了「每个对象都必然如此」与「必然地每个对象都如此」。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f9", kind: "position", front: "本质论（essentialism）与 Fine 的「本质 ≠ 必然」", back: "本质论主张对象有本质属性，失之则不再是它。Kit Fine 主张本质比必然更基本：苏格拉底必然属于单元集{苏格拉底}，但这不算他的本质，因为本质属性应当**解释**对象为何如此，而单元集归属没有解释力。", where: "philo-metaphysics-3" },
        { id: "philo-metaphysics-3-f10", kind: "term", front: "可及关系（accessibility relation R）", back: "可能世界语义中「从哪个世界能看到哪些世界」的关系。它决定模态逻辑的强弱：R 自反则 □P → P 成立（必然蕴含现实）；R 传递则 □P → □□P 成立；R 全通则得到 S5，所有世界互相可及。", hint: "公理不是口味，是对 R 的要求。", where: "philo-metaphysics-3" }
      ],
