            "把模态与认识论分开：这句话是后验知道的（认识论），它是否必然（形而上学）是另一个问题。混在一起会让文章失去焦点。",
            "约定论的反驳通常最强：如果「水」的意义是我们规定的，为什么发现成分时会有「发现了世界的事实」这种感觉？把这个问题写进文章并尝试回答。",
