            { t: "若甲队不开枪，乙队仍会开枪且致命，死亡照样发生。", role: "premise" },
            { t: "两队行刑队同时开枪，每颗子弹都致命。", role: "noise" },
            { t: "甲队开枪是死亡的原因（直觉与法律责任均如此判定）。", role: "premise" }
